def cross(a,b):
    return a[0]*b[1]-a[1]*b[0]
def overlap(subject,clip):
    out=[np.array(v,dtype=float) for v in subject]
    clip=np.asarray(clip,dtype=float)
    orient=np.sign(sum(cross(clip[i],clip[(i+1)%len(clip)]) for i in range(len(clip))))
    for i,a in enumerate(clip):
        b=clip[(i+1)%len(clip)]
        inp,out=out,[]
        if not inp: break
        prev=inp[-1]
        pd=orient*cross(b-a,prev-a)
